formula:
=LET(
  tc_index; SWITCH(P9; "ARS"; 9; "USD"; 10; "AUD"; 11; "EUR"; 12; 9);
  tc_col; CHOOSECOLS(AM4:AX; tc_index);
  ingresos_prev; IFERROR(SUM(FILTER(IFERROR(AM4:AM / tc_col; 0); AN4:AN = "Ingreso")); 0);
  variacion; IFERROR((I11 - ingresos_prev) / ingresos_prev; 0);
  TEXT(variacion; "+0%;-0%;0%") & " respecto mes anterior"
)

=LET(
  tc_index; SWITCH(P9; "ARS"; 9; "USD"; 10; "AUD"; 11; "EUR"; 12; 9);
  tc_col; CHOOSECOLS(AM4:AX; tc_index);
  egresos_prev; IFERROR(SUM(FILTER(IFERROR(AM4:AM / tc_col; 0); AN4:AN = "Egreso")); 0);
  variacion; IFERROR((L11 - egresos_prev) / egresos_prev; 0);
  TEXT(variacion; "+0%;-0%;0%") & " respecto mes anterior"
)

=LET(
  mes_num; MATCH(P4; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  fecha_inicio; TEXT(DATE(P6; mes_num; 1); "yyyy-mm-dd");
  fecha_fin; TEXT(EOMONTH(DATE(P6; mes_num; 1); 0); "yyyy-mm-dd");
  QUERY(
    Registros!I2:T;
    "SELECT * WHERE Col7 >= date '" & fecha_inicio & "' AND Col7 <= date '" & fecha_fin & "'";
    0
  )
)

=ARRAYFORMULA(
  IF(Y4:Y=""; "";
    LET(
      tasa_origen; IF(AA4:AA="ARS"; AG4:AG; IF(AA4:AA="USD"; AH4:AH; IF(AA4:AA="AUD"; AI4:AI; IF(AA4:AA="EUR"; AJ4:AJ; 1))));
      tasa_destino; IF(P9="ARS"; AG4:AG; IF(P9="USD"; AH4:AH; IF(P9="AUD"; AI4:AI; IF(P9="EUR"; AJ4:AJ; 1))));
      IFERROR((Y4:Y * tasa_origen) / tasa_destino; 0)
    )
  )
)

=LET(
  mes_num; MATCH(P4; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  fecha_inicio; TEXT(DATE(P6; mes_num - 1; 1); "yyyy-mm-dd");
  fecha_fin; TEXT(EOMONTH(DATE(P6; mes_num - 1; 1); 0); "yyyy-mm-dd");
  QUERY(
    Registros!I2:T;
    "SELECT * WHERE Col7 >= date '" & fecha_inicio & "' AND Col7 <= date '" & fecha_fin & "'";
    0
  )
)

=LET(
  ingresos_traspaso; SUMIFS(AZ4:AZ; AP4:AP; "Traspaso"; AO4:AO; "Ingreso");
  egresos_traspaso; SUMIFS(AZ4:AZ; AP4:AP; "Traspaso"; AO4:AO; "Egreso");
  diferencia; ROUND(ingresos_traspaso - egresos_traspaso; 2);

  IF(diferencia = 0;
    "Traspasos balanceados";
    "Descuadre en Traspasos por " & TEXT(diferencia; "$ #.##0,00")
  )
)

=LET(
  liquidez_ars; S4 + (S5 * $AL$4) + (S6 * $AL$5) + (S7 * $AL$6);
  tasa_cambio; IFERROR(SWITCH($I$9; "ARS"; 1; "USD"; $AL$4; "AUD"; $AL$5; "EUR"; $AL$6); 1);
  liquidez_moneda; liquidez_ars / tasa_cambio;

  rem_ahorro; MAX(0; ($S$13-$S$14-$S$15) - ($U$13-$U$14-$U$15));
  rem_fijos; MAX(0; $S$14 - $U$14);
  rem_var; MAX(0; $S$15 - $U$15);
  suma_rem; rem_ahorro + rem_fijos + rem_var;

  IF(suma_rem > 0; liquidez_moneda * (rem_ahorro / suma_rem); liquidez_moneda)
)

=LET(
  liquidez_ars; S4 + (S5 * $AL$4) + (S6 * $AL$5) + (S7 * $AL$6);
  tasa_cambio; IFERROR(SWITCH($I$9; "ARS"; 1; "USD"; $AL$4; "AUD"; $AL$5; "EUR"; $AL$6); 1);
  liquidez_moneda; liquidez_ars / tasa_cambio;

  rem_ahorro; MAX(0; ($S$13-$S$14-$S$15) - ($U$13-$U$14-$U$15));
  rem_fijos; MAX(0; $S$14 - $U$14);
  rem_var; MAX(0; $S$15 - $U$15);
  suma_rem; rem_ahorro + rem_fijos + rem_var;

  IF(suma_rem > 0; liquidez_moneda * (rem_fijos / suma_rem); 0)
)

=LET(
  liquidez_ars; S4 + (S5 * $AL$4) + (S6 * $AL$5) + (S7 * $AL$6);
  tasa_cambio; IFERROR(SWITCH($I$9; "ARS"; 1; "USD"; $AL$4; "AUD"; $AL$5; "EUR"; $AL$6); 1);
  liquidez_moneda; liquidez_ars / tasa_cambio;

  rem_ahorro; MAX(0; ($S$13-$S$14-$S$15) - ($U$13-$U$14-$U$15));
  rem_fijos; MAX(0; $S$14 - $U$14);
  rem_var; MAX(0; $S$15 - $U$15);
  suma_rem; rem_ahorro + rem_fijos + rem_var;

  IF(suma_rem > 0; liquidez_moneda * (rem_var / suma_rem); 0)
)

=LET(
  monto_neto; ARRAYFORMULA(IF(AO4:AO="Egreso"; -AN4:AN; AN4:AN));
  proyectos; ARRAYFORMULA(IFERROR(VLOOKUP(AR4:AR; 'Plan de Cuentas'!R:T; 3; 0); ""));
  tipos_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyectos; 'Plan de Cuentas'!V:W; 2; 0); ""));
  cond_riqueza; ARRAYFORMULA((tipos_proy<>"Liquidez") * (tipos_proy<>"") > 0);

  SUM(IFERROR(FILTER(monto_neto; AS4:AS="ARS"; cond_riqueza); 0))
)

=LET(
  monto_neto; ARRAYFORMULA(IF(AO4:AO="Egreso"; -AN4:AN; AN4:AN));
  proyectos; ARRAYFORMULA(IFERROR(VLOOKUP(AR4:AR; 'Plan de Cuentas'!R:T; 3; 0); ""));
  tipos_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyectos; 'Plan de Cuentas'!V:W; 2; 0); ""));
  cond_riqueza; ARRAYFORMULA((tipos_proy<>"Liquidez") * (tipos_proy<>"") > 0);

  SUM(IFERROR(FILTER(monto_neto; AS4:AS="USD"; cond_riqueza); 0))
)

=LET(
  monto_neto; ARRAYFORMULA(IF(AO4:AO="Egreso"; -AN4:AN; AN4:AN));
  proyectos; ARRAYFORMULA(IFERROR(VLOOKUP(AR4:AR; 'Plan de Cuentas'!R:T; 3; 0); ""));
  tipos_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyectos; 'Plan de Cuentas'!V:W; 2; 0); ""));
  cond_riqueza; ARRAYFORMULA((tipos_proy<>"Liquidez") * (tipos_proy<>"") > 0);

  SUM(IFERROR(FILTER(monto_neto; AS4:AS="AUD"; cond_riqueza); 0))
)

=LET(
  monto_neto; ARRAYFORMULA(IF(AO4:AO="Egreso"; -AN4:AN; AN4:AN));
  proyectos; ARRAYFORMULA(IFERROR(VLOOKUP(AR4:AR; 'Plan de Cuentas'!R:T; 3; 0); ""));
  tipos_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyectos; 'Plan de Cuentas'!V:W; 2; 0); ""));
  cond_riqueza; ARRAYFORMULA((tipos_proy<>"Liquidez") * (tipos_proy<>"") > 0);

  SUM(IFERROR(FILTER(monto_neto; AS4:AS="EUR"; cond_riqueza); 0))
)

=LET(
  monto_neto; ARRAYFORMULA(IF(AO4:AO="Egreso"; -AN4:AN; AN4:AN));
  cond_inicio; ARRAYFORMULA(AP4:AP<>"Inicio Mes");

  proyectos; ARRAYFORMULA(IFERROR(VLOOKUP(AR4:AR; 'Plan de Cuentas'!R:T; 3; 0); ""));
  tipos_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyectos; 'Plan de Cuentas'!V:W; 2; 0); ""));

  cond_ahorro; ARRAYFORMULA((tipos_proy<>"Liquidez") * (tipos_proy<>"") > 0);

  suma_ars; SUM(IFERROR(FILTER(monto_neto; AS4:AS="ARS"; cond_inicio; cond_ahorro); 0));
  suma_usd; SUM(IFERROR(FILTER(monto_neto; AS4:AS="USD"; cond_inicio; cond_ahorro); 0));
  suma_aud; SUM(IFERROR(FILTER(monto_neto; AS4:AS="AUD"; cond_inicio; cond_ahorro); 0));
  suma_eur; SUM(IFERROR(FILTER(monto_neto; AS4:AS="EUR"; cond_inicio; cond_ahorro); 0));

  total_ars; suma_ars + (suma_usd * $AL$4) + (suma_aud * $AL$5) + (suma_eur * $AL$6);

  tasa_cambio; IFERROR(SWITCH($I$9; "ARS"; 1; "USD"; $AL$4; "AUD"; $AL$5; "EUR"; $AL$6); 1);

  total_ars / tasa_cambio
)

=IFERROR(QUERY(
  ARRAYFORMULA({AR4:AR \ AS4:AS \ IF(AO4:AO="Egreso"; -AN4:AN; AN4:AN)});
  "SELECT Col1, Col2, SUM(Col3) 
   WHERE Col1 IS NOT NULL AND Col1 <> '' 
   GROUP BY Col1, Col2 
   ORDER BY SUM(Col3) DESC 
   LABEL Col1 '', Col2 '', SUM(Col3) ''";
  0
); {"" \ "" \ ""})

=LET(
  medio; AR4:AR;
  moneda; AS4:AS;

  monto_neto; ARRAYFORMULA(IF(AN4:AN=""; 0; IF(AO4:AO="Egreso"; -AN4:AN; AN4:AN)));

  proyecto; ARRAYFORMULA(IFERROR(VLOOKUP(medio; 'Plan de Cuentas'!R:T; 3; 0); ""));
  tipo_proy; ARRAYFORMULA(IFERROR(VLOOKUP(proyecto; 'Plan de Cuentas'!V:W; 2; 0); ""));

  tasa_origen; ARRAYFORMULA(IF(moneda="USD"; $AL$4; IF(moneda="AUD"; $AL$5; IF(moneda="EUR"; $AL$6; 1))));
  tasa_destino; IFERROR(SWITCH($I$9; "ARS"; 1; "USD"; $AL$4; "AUD"; $AL$5; "EUR"; $AL$6); 1);

  monto_convertido; ARRAYFORMULA(IFERROR((monto_neto * tasa_origen) / tasa_destino; 0));

  condicion; ARRAYFORMULA((proyecto<>"") * (tipo_proy<>"Liquidez") > 0);

  proy_filtrado; FILTER(proyecto; condicion);
  monto_filtrado; FILTER(monto_convertido; condicion);

  resultado_query; IFERROR(QUERY(
    {proy_filtrado \ monto_filtrado};
    "SELECT Col1, SUM(Col2) 
     GROUP BY Col1 
     ORDER BY SUM(Col2) DESC 
     LABEL Col1 '', SUM(Col2) ''";
    0
  ); {"" \ ""});

  columna_aj; INDEX(resultado_query; 0; 1);
  columna_al; INDEX(resultado_query; 0; 2);
  columna_ak_vacia; ARRAYFORMULA(IF(columna_aj<>""; ""; ""));

  {columna_aj \ columna_ak_vacia \ columna_al}
)

=LET(
  mes_num; MATCH(I4; SPLIT("Enero,Febrero,Marzo,Abril,Mayo,Junio,Julio,Agosto,Septiembre,Octubre,Noviembre,Diciembre"; ","); 0);
  fecha_inicio; TEXT(DATE(I6; mes_num; 1); "yyyy-mm-dd");
  fecha_fin; TEXT(EOMONTH(DATE(I6; mes_num; 1); 0); "yyyy-mm-dd");
  QUERY(
    Registros!I2:T;
    "SELECT * WHERE Col7 >= date '" & fecha_inicio & "' AND Col7 <= date '" & fecha_fin & "'";
    0
  )
)

=ARRAYFORMULA(
  IF(AN4:AN=""; "";
    LET(
      tasa_origen; IF(AS4:AS="ARS"; AV4:AV; IF(AS4:AS="USD"; AW4:AW; IF(AS4:AS="AUD"; AX4:AX; IF(AS4:AS="EUR"; AY4:AY; 1))));
      tasa_destino; IF(I9="ARS"; AV4:AV; IF(I9="USD"; AW4:AW; IF(I9="AUD"; AX4:AX; IF(I9="EUR"; AY4:AY; 1))));
      IFERROR((AN4:AN * tasa_origen) / tasa_destino; 0)
    )
  )
)

=IFERROR(QUERY(
  {Registros!I2:T};
  "SELECT Col1, Col2, Col3, Col5, Col6, Col7, Col8 WHERE Col1 IS NOT NULL ORDER BY Col7 DESC LIMIT 15";
  0
); "")

